window.LECCIONES = window.LECCIONES || {};
LECCIONES.react = { lang: 'jsx', capitulos: [
  { t: 'JSX y componentes', secciones: [
    { n: '1.1', t: '¿Qué es React?', m: '3 min', b: 'React es una librería de JavaScript para construir interfaces a partir de componentes: piezas reutilizables que combinan estructura, estilo y lógica. Tú describes cómo debe verse la interfaz según los datos y React se encarga de actualizar el DOM.', k: ['La interfaz se divide en componentes.', 'Declarativo: describes el resultado, no los pasos.', 'React actualiza solo lo que cambia.'], c: 'function App() {\n  return <h1>Hola, DAW</h1>;\n}', tip: 'antes de React conviene dominar JavaScript: arrays, objetos y funciones flecha.' },
    { n: '1.2', t: 'Crear un proyecto con Vite', m: '3 min', b: 'La forma recomendada de empezar es con Vite, que crea el proyecto y arranca un servidor de desarrollo que recarga al guardar. Necesitas Node.js instalado.', k: ['npm create vite@latest crea el proyecto.', 'npm run dev arranca el servidor local.', 'El código principal está en src/.'], c: 'npm create vite@latest mi-app -- --template react\ncd mi-app\nnpm install\nnpm run dev', tip: 'si npm no existe, instalad primero Node.js LTS.' },
    { n: '1.3', t: 'JSX', m: '4 min', b: 'JSX permite escribir algo parecido a HTML dentro de JavaScript. Las expresiones van entre llaves {}, class se escribe className y todo debe devolver un único elemento padre (o un fragmento <>…</>).', k: ['{expresión} inserta valores de JavaScript.', 'className en lugar de class.', 'Un solo elemento raíz o un fragmento <> </>.'], c: 'const nombre = "Ana";\nreturn (\n  <>\n    <h1 className="titulo">Hola, {nombre}</h1>\n    <p>Tienes {2 + 1} entradas</p>\n  </>\n);', tip: 'los errores de JSX suelen ser etiquetas sin cerrar: <img /> lleva barra.' },
    { n: '1.4', t: 'Componentes', m: '4 min', b: 'Un componente es una función que devuelve JSX. Su nombre empieza por mayúscula y se usa como una etiqueta. Lo normal es tener un archivo por componente y exportarlo para usarlo en otros.', k: ['Nombre en PascalCase: TarjetaTema.', 'Se usa como <TarjetaTema />.', 'export default para usarlo en otro archivo.'], c: '// Cabecera.jsx\nexport default function Cabecera() {\n  return <header><h1>DevPath</h1></header>;\n}\n\n// App.jsx\nimport Cabecera from "./Cabecera";', tip: 'si un componente crece mucho, dividirlo en varios más pequeños.' }
  ]},
  { t: 'Props', secciones: [
    { n: '2.1', t: 'Pasar props', m: '4 min', b: 'Las props son los datos que un componente padre pasa a un hijo, como los atributos en HTML. El hijo las recibe como un objeto y las suele desestructurar. Son de solo lectura.', k: ['<Tarjeta titulo="SQL" />', 'function Tarjeta({ titulo }) { … }', 'Un componente nunca modifica sus props.'], c: 'function Tarjeta({ titulo, nivel }) {\n  return <div><h3>{titulo}</h3><small>{nivel}</small></div>;\n}\n\n<Tarjeta titulo="SQL" nivel="Básico" />', tip: 'pensad en las props como los parámetros de una función.' },
    { n: '2.2', t: 'children', m: '3 min', b: 'Lo que pones entre la etiqueta de apertura y cierre de un componente llega como la prop children. Sirve para crear contenedores reutilizables como tarjetas, modales o layouts.', k: ['children = contenido entre etiquetas.', 'Ideal para envoltorios y layouts.', 'Puede ser texto, JSX u otros componentes.'], c: 'function Caja({ children }) {\n  return <div className="caja">{children}</div>;\n}\n\n<Caja><p>Contenido dentro de la caja</p></Caja>', tip: 'un componente Layout con children evita repetir cabecera y pie en cada página.' },
    { n: '2.3', t: 'Renderizado condicional', m: '3 min', b: 'Para mostrar algo solo si se cumple una condición se usa el operador ternario o &&. Así la interfaz cambia según los datos.', k: ['cond ? <A /> : <B />', 'cond && <A /> muestra A solo si cond es true.', 'Cuidado: 0 && algo pinta un 0.'], c: 'function Estado({ agotado }) {\n  return agotado ? <span>Agotado</span> : <button>Comprar</button>;\n}', tip: 'con && usad siempre una condición booleana: lista.length > 0 && …' },
    { n: '2.4', t: 'Listas y key', m: '4 min', b: 'Para pintar una lista se usa map sobre un array y se devuelve un elemento por cada dato. Cada elemento necesita una prop key única y estable para que React sepa qué ha cambiado.', k: ['array.map(item => <li key={item.id}>…</li>)', 'key debe ser única entre hermanos.', 'Evita usar el índice como key si la lista cambia.'], c: 'const temas = [{ id: 1, nombre: "HTML" }, { id: 2, nombre: "CSS" }];\n\n<ul>\n  {temas.map(t => <li key={t.id}>{t.nombre}</li>)}\n</ul>', tip: 'el aviso «Each child should have a unique key» significa que falta key.' }
  ]},
  { t: 'Estado', secciones: [
    { n: '3.1', t: 'useState', m: '4 min', b: 'El estado son los datos que cambian con el tiempo dentro de un componente. useState devuelve el valor actual y una función para cambiarlo. Cuando el estado cambia, React vuelve a pintar el componente.', k: ['const [valor, setValor] = useState(inicial);', 'Nunca cambies el estado directamente.', 'Cambiar el estado vuelve a renderizar.'], c: 'import { useState } from "react";\n\nfunction Contador() {\n  const [n, setN] = useState(0);\n  return <button onClick={() => setN(n + 1)}>Clics: {n}</button>;\n}', tip: 'el contador es el «hola mundo» del estado: hacedlo vosotros.' },
    { n: '3.2', t: 'Eventos', m: '3 min', b: 'Los eventos en React se escriben en camelCase (onClick, onChange, onSubmit) y reciben una función, no una llamada. Dentro puedes actualizar el estado.', k: ['onClick={manejar}, no onClick={manejar()}.', 'Para pasar argumentos: onClick={() => borrar(id)}.', 'e.preventDefault() en formularios.'], c: 'function Boton() {\n  const avisar = () => alert("Hola");\n  return <button onClick={avisar}>Saludar</button>;\n}', tip: 'si la función se ejecuta al cargar la página, os sobran los paréntesis.' },
    { n: '3.3', t: 'Formularios controlados', m: '4 min', b: 'En un input controlado, su valor vive en el estado y se actualiza con onChange. Así siempre sabes lo que hay escrito y puedes validarlo o enviarlo.', k: ['value={estado} + onChange={e => setEstado(e.target.value)}', 'El estado es la única fuente de verdad.', 'onSubmit en el form, con preventDefault.'], c: 'const [email, setEmail] = useState("");\n\n<form onSubmit={e => { e.preventDefault(); console.log(email); }}>\n  <input value={email} onChange={e => setEmail(e.target.value)} />\n</form>', tip: 'sin onChange, el input controlado no deja escribir.' },
    { n: '3.4', t: 'Levantar el estado', m: '4 min', b: 'Cuando dos componentes necesitan el mismo dato, el estado se mueve al padre común y se pasa por props, junto con las funciones para cambiarlo. Así ambos están siempre sincronizados.', k: ['El estado vive en el padre común.', 'Se baja como props.', 'El hijo avisa al padre con una función.'], c: 'function App() {\n  const [filtro, setFiltro] = useState("Todos");\n  return <>\n    <Filtros valor={filtro} onCambiar={setFiltro} />\n    <ListaTemas filtro={filtro} />\n  </>;\n}', tip: 'dibujad el árbol de componentes antes de decidir dónde va cada estado.' }
  ]},
  { t: 'Efectos y datos', secciones: [
    { n: '4.1', t: 'useEffect', m: '4 min', b: 'useEffect ejecuta código después de renderizar, para cosas que salen de React: pedir datos, usar temporizadores o tocar el título de la página. El array de dependencias decide cuándo se repite.', k: ['useEffect(() => { … }, [])', '[] = solo al montar el componente.', '[valor] = cada vez que cambie valor.'], c: 'useEffect(() => {\n  document.title = `Tienes ${n} entradas`;\n}, [n]);', tip: 'sin array de dependencias, el efecto se ejecuta en cada render.' },
    { n: '4.2', t: 'Cargar datos de una API', m: '5 min', b: 'Lo habitual es pedir los datos en un useEffect con array vacío, guardarlos en estado y mostrar un mensaje mientras cargan o si hay error.', k: ['Tres estados: cargando, datos y error.', 'async dentro del efecto, no en el efecto.', 'Muestra feedback al usuario.'], c: 'const [temas, setTemas] = useState([]);\nuseEffect(() => {\n  async function cargar() {\n    const res = await fetch("/api/temas");\n    setTemas(await res.json());\n  }\n  cargar();\n}, []);', tip: 'la función de useEffect no puede ser async: cread una dentro.' },
    { n: '4.3', t: 'Dependencias y limpieza', m: '4 min', b: 'Si un efecto crea algo que sigue vivo (un intervalo, una suscripción), debe devolver una función de limpieza que React ejecuta antes de repetir el efecto o al desmontar el componente.', k: ['return () => { … } limpia el efecto.', 'Evita fugas de memoria e intervalos duplicados.', 'Incluye en dependencias todo lo que uses.'], c: 'useEffect(() => {\n  const id = setInterval(() => setSeg(s => s + 1), 1000);\n  return () => clearInterval(id);\n}, []);', tip: 'si un temporizador va el doble de rápido, os falta la limpieza.' },
    { n: '4.4', t: 'Desplegar tu app', m: '3 min', b: 'npm run build genera una versión optimizada en la carpeta dist. Plataformas como Vercel detectan Vite, ejecutan el build y publican la web cada vez que haces push a GitHub.', k: ['npm run build crea dist/.', 'Vercel despliega en cada push.', 'Las ramas generan vistas previas.'], c: 'npm run build\nnpx vercel', tip: 'esta misma web se publica en Vercel: el flujo es el mismo.' }
  ]}
]};
LECCIONES.react.capitulos.push(
  { t: 'Hooks avanzados', d: 'useRef, useMemo, useReducer y hooks propios.', secciones: [
    { n: '5.1', t: 'useRef', m: '4 min', b: 'useRef guarda un valor que persiste entre renders sin provocar uno nuevo al cambiar. Su uso más común es acceder a un elemento del DOM, por ejemplo para darle el foco o medirlo.', k: ['const ref = useRef(null); <input ref={ref} />', 'ref.current es el elemento o el valor.', 'Cambiar ref.current no vuelve a renderizar.'], c: 'function Buscador() {\n  const input = useRef(null);\n  useEffect(() => { input.current.focus(); }, []);\n  return <input ref={input} placeholder="Buscar tema" />;\n}', tip: 'si necesitáis tocar el DOM directamente en React, casi siempre es con useRef.' },
    { n: '5.2', t: 'useMemo y useCallback', m: '4 min', b: 'useMemo guarda el resultado de un cálculo costoso y solo lo repite si cambian sus dependencias. useCallback hace lo mismo con funciones. Úsalos cuando haya un problema real de rendimiento, no por defecto.', k: ['useMemo(() => calculo, [deps])', 'useCallback(fn, [deps]) memoriza una función.', 'Optimiza solo cuando lo necesites.'], c: 'const filtrados = useMemo(\n  () => temas.filter(t => t.nombre.toLowerCase().includes(busqueda)),\n  [temas, busqueda]\n);', tip: 'React DevTools (Profiler) os dice qué componentes se renderizan de más.' },
    { n: '5.3', t: 'useReducer', m: '5 min', b: 'useReducer gestiona estados complejos con una función reductora que recibe el estado actual y una acción, y devuelve el nuevo estado. Es útil cuando varias acciones modifican el mismo estado, como un carrito.', k: ['const [estado, dispatch] = useReducer(reducer, inicial);', 'dispatch({ type: "añadir", producto })', 'El reducer nunca muta: devuelve un estado nuevo.'], c: 'function carrito(estado, accion) {\n  switch (accion.type) {\n    case "añadir": return [...estado, accion.producto];\n    case "vaciar": return [];\n    default: return estado;\n  }\n}\nconst [items, dispatch] = useReducer(carrito, []);\ndispatch({ type: "añadir", producto: { nombre: "Entrada" } });', tip: 'si tenéis cinco useState relacionados, probad un useReducer.' },
    { n: '5.4', t: 'Hooks personalizados', m: '4 min', b: 'Un hook personalizado es una función que empieza por use y combina otros hooks para reutilizar lógica entre componentes, como cargar datos o leer de localStorage.', k: ['Su nombre empieza por use.', 'Reutiliza lógica, no interfaz.', 'Puede usar otros hooks dentro.'], c: 'function useLocalStorage(clave, inicial) {\n  const [valor, setValor] = useState(() =>\n    JSON.parse(localStorage.getItem(clave)) ?? inicial);\n  useEffect(() => { localStorage.setItem(clave, JSON.stringify(valor)); }, [clave, valor]);\n  return [valor, setValor];\n}\nconst [progreso, setProgreso] = useLocalStorage("progreso", []);', tip: 'un useFetch propio es un ejercicio excelente para entender los hooks.' }
  ]},
  { t: 'Context y estado global', d: 'Compartir datos sin pasar props por todo el árbol.', secciones: [
    { n: '6.1', t: 'El problema del prop drilling', m: '3 min', b: 'Cuando un dato lo necesitan componentes muy profundos, pasarlo por props a través de todos los intermedios (prop drilling) se vuelve pesado. Context permite que cualquier componente del árbol lo lea directamente.', k: ['Prop drilling = pasar props por componentes que no las usan.', 'Context comparte datos con todo un subárbol.', 'Útil para usuario, tema o idioma.'], c: '// Sin Context: App → Layout → Menu → Avatar (usuario pasa por todos)\n<Layout usuario={usuario} />', tip: 'si una prop pasa por más de tres niveles sin usarse, pensad en Context.' },
    { n: '6.2', t: 'createContext y useContext', m: '5 min', b: 'Se crea un contexto con createContext, se envuelve la parte de la app con su Provider dando un value, y cualquier componente hijo lo lee con useContext.', k: ['const Ctx = createContext(valorPorDefecto);', '<Ctx.Provider value={…}>…</Ctx.Provider>', 'const valor = useContext(Ctx);'], c: 'const TemaContext = createContext("claro");\n\nfunction App() {\n  const [tema, setTema] = useState("claro");\n  return (\n    <TemaContext.Provider value={{ tema, setTema }}>\n      <Pagina />\n    </TemaContext.Provider>\n  );\n}\nfunction BotonTema() {\n  const { tema, setTema } = useContext(TemaContext);\n  return <button onClick={() => setTema(tema === "claro" ? "oscuro" : "claro")}>{tema}</button>;\n}', tip: 'cread un archivo por contexto con su Provider y un hook useTema().' },
    { n: '6.3', t: 'Context + useReducer', m: '4 min', b: 'Combinar Context con useReducer da un estado global sencillo sin librerías: el reducer define cómo cambia el estado y el Provider lo comparte junto con dispatch.', k: ['El Provider expone estado y dispatch.', 'Cualquier componente puede despachar acciones.', 'Patrón muy común para carritos y sesiones.'], c: 'const CarritoContext = createContext();\nexport function CarritoProvider({ children }) {\n  const [items, dispatch] = useReducer(carrito, []);\n  return <CarritoContext.Provider value={{ items, dispatch }}>{children}</CarritoContext.Provider>;\n}\nexport const useCarrito = () => useContext(CarritoContext);', tip: 'este patrón cubre la mayoría de proyectos de clase.' },
    { n: '6.4', t: 'Librerías de estado', m: '3 min', b: 'En aplicaciones grandes se usan librerías como Zustand o Redux Toolkit para el estado global, y TanStack Query para los datos que vienen del servidor (con caché y recarga automática).', k: ['Zustand: estado global muy sencillo.', 'Redux Toolkit: estándar en empresas grandes.', 'TanStack Query: datos del servidor con caché.'], c: 'import { create } from "zustand";\nconst useCarrito = create((set) => ({\n  items: [],\n  añadir: (p) => set((s) => ({ items: [...s.items, p] }))\n}));', tip: 'no empecéis por Redux: Context o Zustand bastan para casi todo.' }
  ]},
  { t: 'Rutas con React Router', d: 'Varias páginas, enlaces y parámetros.', secciones: [
    { n: '7.1', t: 'Instalar y definir rutas', m: '4 min', b: 'React Router permite tener varias «páginas» en una app de React cambiando la URL sin recargar. Se definen las rutas asociando cada path a un componente.', k: ['npm install react-router-dom', '<BrowserRouter> envuelve la app.', '<Routes> y <Route path element>.'], c: 'import { BrowserRouter, Routes, Route } from "react-router-dom";\n\n<BrowserRouter>\n  <Routes>\n    <Route path="/" element={<Inicio />} />\n    <Route path="/temas" element={<Temas />} />\n    <Route path="*" element={<NoEncontrado />} />\n  </Routes>\n</BrowserRouter>', tip: 'la ruta * captura todo lo que no existe: vuestra página 404.' },
    { n: '7.2', t: 'Link y NavLink', m: '3 min', b: 'Para navegar se usa <Link to> en lugar de <a href>, así no se recarga la página. <NavLink> añade una clase cuando la ruta está activa, ideal para menús.', k: ['<Link to="/temas">Temas</Link>', 'NavLink marca el enlace activo.', 'Para enlaces externos sigue usando <a>.'], c: 'import { NavLink } from "react-router-dom";\n\n<nav>\n  <NavLink to="/" end>Inicio</NavLink>\n  <NavLink to="/temas">Temas</NavLink>\n</nav>', tip: 'si la app se recarga al cambiar de página, estáis usando <a> en vez de Link.' },
    { n: '7.3', t: 'Parámetros de ruta', m: '4 min', b: 'Una ruta puede tener partes variables, como /tema/:slug. Dentro del componente se leen con useParams. Así una sola página muestra cualquier tema, igual que hace DevPath.', k: ['<Route path="/tema/:slug" element={<Tema />} />', 'const { slug } = useParams();', 'useSearchParams lee ?filtro=… de la URL.'], c: 'function Tema() {\n  const { slug } = useParams();\n  const tema = TEMAS.find(t => t.slug === slug);\n  if (!tema) return <p>Tema no encontrado</p>;\n  return <h1>{tema.nombre}</h1>;\n}', tip: 'DevPath hace esto mismo con /tema/sql, pero sin React.' },
    { n: '7.4', t: 'Navegar desde código y layouts', m: '4 min', b: 'useNavigate cambia de página desde código, por ejemplo tras enviar un formulario. Con rutas anidadas y <Outlet> defines un layout común (cabecera y pie) para varias páginas.', k: ['const navigate = useNavigate(); navigate("/gracias")', '<Outlet /> pinta la ruta hija.', 'Layout común sin repetir código.'], c: '<Route element={<Layout />}>\n  <Route path="/" element={<Inicio />} />\n  <Route path="/temas" element={<Temas />} />\n</Route>\n\nfunction Layout() {\n  return <><Cabecera /><Outlet /><Pie /></>;\n}', tip: 'en Vercel, una SPA necesita una regla para que todas las rutas sirvan index.html.' }
  ]},
  { t: 'Buenas prácticas y testing', d: 'Estructura, estilos, variables de entorno y pruebas.', secciones: [
    { n: '8.1', t: 'Estructura de carpetas', m: '3 min', b: 'Organizar bien los archivos facilita trabajar en equipo. Una estructura habitual separa componentes reutilizables, páginas, hooks, contextos y servicios para llamar a la API.', k: ['components/, pages/, hooks/, context/, services/.', 'Un componente por archivo.', 'Agrupa por funcionalidad cuando el proyecto crece.'], c: 'src/\n  components/  Boton.jsx  Tarjeta.jsx\n  pages/       Inicio.jsx  Tema.jsx\n  hooks/       useFetch.js\n  context/     CarritoContext.jsx\n  services/    api.js\n  App.jsx', tip: 'acordad la estructura con el grupo antes de empezar a programar.' },
    { n: '8.2', t: 'Estilos en React', m: '4 min', b: 'Hay varias formas de dar estilo: CSS normal importado, CSS Modules (clases con ámbito local para que no choquen), Tailwind CSS o librerías de componentes. En React, la clase se pone con className.', k: ['import "./Boton.css" o import s from "./Boton.module.css".', 'CSS Modules evita conflictos de nombres.', 'Tailwind es muy popular con React.'], c: 'import styles from "./Tarjeta.module.css";\n\nexport function Tarjeta({ titulo }) {\n  return <div className={styles.tarjeta}>{titulo}</div>;\n}', tip: 'CSS Modules viene listo en Vite: solo hay que nombrar el archivo .module.css.' },
    { n: '8.3', t: 'Variables de entorno', m: '3 min', b: 'Las URLs de la API o claves públicas se guardan en un archivo .env para no escribirlas en el código. En Vite deben empezar por VITE_ y se leen con import.meta.env. Nunca pongas secretos en el frontend: cualquiera puede verlos.', k: ['.env → VITE_API_URL=https://…', 'import.meta.env.VITE_API_URL', 'El .env no se sube a Git.'], c: '# .env\nVITE_API_URL=https://api.mi-proyecto.com\n\n// api.js\nconst API = import.meta.env.VITE_API_URL;\nexport const getTemas = () => fetch(`${API}/temas`).then(r => r.json());', tip: 'en Vercel, las variables de entorno se configuran en los ajustes del proyecto.' },
    { n: '8.4', t: 'Pruebas con Vitest y Testing Library', m: '5 min', b: 'Las pruebas automáticas comprueban que tus componentes funcionan y evitan romper algo al cambiar código. Vitest ejecuta los tests y Testing Library permite renderizar componentes y simular lo que hace un usuario.', k: ['npm install -D vitest @testing-library/react', 'render, screen y fireEvent / userEvent.', 'Prueba lo que ve el usuario, no la implementación.'], c: 'import { render, screen, fireEvent } from "@testing-library/react";\nimport Contador from "./Contador";\n\ntest("suma al hacer clic", () => {\n  render(<Contador />);\n  fireEvent.click(screen.getByRole("button"));\n  expect(screen.getByText("Clics: 1")).toBeInTheDocument();\n});', tip: 'saber hacer tests es algo que valoran mucho en las prácticas de empresa.' }
  ]}
);
